const app=document.querySelector('#app');let projects=[...window.baseProjects],me=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function home(){import('/assets/portfolio-pages.js?v=40-work-scale-motion').then(m=>{if(['/', '/index.html', '/work'].includes(location.pathname))window.disposeIntro=m.mountPortfolio(app,projects,{work:location.pathname==='/work'})}).catch(()=>{app.innerHTML='<section class="page"><h1>PORTFOLIO</h1><p>页面暂时未能加载，请刷新。</p></section>'})}
async function showProject(p){
 const m=await import('/assets/project-page.js?v=37-stock-layout');
 if(location.pathname.startsWith('/project/')&&decodeURIComponent(location.pathname.slice(9))===p.id)window.disposeIntro=m.mountProjectPage(app,p);
}
async function admin(){if(!me){app.innerHTML='<section class="page"><a class="return" href="/work">← 返回作品页</a><h1>项目管理</h1><p>请使用网站所有者账号登录后上传。</p><a href="/admin" target="_top">登录 ChatGPT</a></section>';return}app.innerHTML=`<section class="page"><a class="return" href="/work">← 返回作品页</a><span class="eyebrow">YOUR PRIVATE STUDIO</span><h1>上传新项目</h1><p class="status-note">提交后保存到网站，并加入顶部导航。第一张图片用作封面。支持 JPG、PNG、WebP，每张最多 8MB，最多 8 张。</p><form id="upload-form"><div class="form-grid"><label>项目名称<input name="title" maxlength="80" required placeholder="例如：New Project"></label><label>设计类别<input name="tags" maxlength="160" required placeholder="BRAND / UI / MOTION"></label><label class="span-two">一句话介绍<input name="summary" maxlength="300" required></label><label class="span-two">项目说明<textarea name="description" maxlength="6000" required></textarea></label><label class="span-two">项目图片<input type="file" name="images" accept="image/jpeg,image/png,image/webp" multiple required></label></div><div class="previews"></div><p class="form-status" role="status"></p><button type="submit" class="submit">提交项目 ↗</button></form><h2>已上传项目</h2><div>${projects.filter(p=>p.custom).map(p=>`<div class="admin-item"><span>${esc(p.title)}</span><a href="/project/${p.id}">查看 ↗</a></div>`).join('')||'<p>还没有新增项目。</p>'}</div></section>`;const f=document.querySelector('#upload-form');let urls=[];f.images.onchange=()=>{urls.forEach(URL.revokeObjectURL);urls=[...f.images.files].map(x=>URL.createObjectURL(x));document.querySelector('.previews').innerHTML=urls.map(u=>`<img src="${u}" alt="待上传项目图片">`).join('')};f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button'),status=f.querySelector('.form-status');const files=[...f.images.files];if(files.length>8||files.some(x=>x.size>8*1024*1024)||files.reduce((n,x)=>n+x.size,0)>32*1024*1024){status.textContent='最多 8 张图片，每张不超过 8MB，总计不超过 32MB。';return}b.disabled=true;status.textContent='正在上传并保存，请稍候…';try{const r=await fetch('/api/projects',{method:'POST',body:new FormData(f)});const data=await r.json();if(!r.ok)throw Error(data.error||'上传失败');projects.push(data);urls.forEach(URL.revokeObjectURL);navigate('/project/'+data.id)}catch(e){status.textContent=e.message;b.disabled=false}}}
async function render(){if(window.disposeIntro){window.disposeIntro();window.disposeIntro=null}document.title='Xichen Zhao — Portfolio';const path=location.pathname;document.body.style.background=path==='/admin'?'#080808':'#ededed';document.body.style.color=path==='/admin'?'#eee':'#151515';if(path==='/'||path==='/index.html'||path==='/work')home();else if(path.startsWith('/project/')){const p=projects.find(x=>x.id===decodeURIComponent(path.slice(9)));if(p){await showProject(p);document.title=p.title+' — Xichen Zhao'}else app.innerHTML='<div class="error">未找到项目。<a href="/">返回首页</a></div>'}else if(path==='/admin')await admin();else if(path==='/about'){const m=await import('/assets/about-tools.js?v=37-stock-layout');if(location.pathname==='/about')window.disposeIntro=m.mountAboutTools(app)}else app.innerHTML='<div class="error">页面不存在。<a href="/">返回首页</a></div>';window.scrollTo(0,0)}
function navigate(path){history.pushState(null,'',path);render()}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.origin===location.origin&&!a.target&&!e.ctrlKey&&!e.metaKey&&!a.pathname.startsWith('/signin')){e.preventDefault();navigate(a.pathname)}});window.addEventListener('popstate',render);
render();(async()=>{try{const [p,m]=await Promise.all([fetch('/api/projects').then(r=>r.ok?r.json():[]),fetch('/api/me').then(r=>r.ok?r.json():{})]);if(Array.isArray(p))projects.push(...p);me=!!m.owner}catch{}if(!['/','/index.html','/about'].includes(location.pathname))render()})();


